    /// ```
    ///
    /// ```html
    /// <button></button>
    /// ```
    ///
    pub UseFocusableInteractive {
        version: "next",
        name: "useFocusableInteractive",
        language: "html",
        sources: &[RuleSource::EslintJsxA11y("interactive-supports-focus").same()],
        recommended: true,
        severity: Severity::Error,
    }
