impl Rule for UseFocusableInteractive {
    type Query = Aria<AnyHtmlTagElement>;
    type State = Box<str>;
    type Signals = Option<Self::State>;
    type Options = UseFocusableInteractiveOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        if node.is_custom_component() {
            return None;
        }

        // Natively interactive elements (e.g. `<button>`) are inherently focusable, so we only
        // consider elements that are not interactive on their own.
        if ctx.aria_roles().is_not_interactive_element(node) {
            let role_attribute = node.find_attribute_by_name("role")?;
            let role_attribute_value = role_attribute.initializer()?.value().ok()?.string_value()?;
            let role_attribute_value = role_attribute_value.trim();

            let tabindex_attribute = node.find_attribute_by_name("tabindex");
            if attribute_has_interactive_role(role_attribute_value) && tabindex_attribute.is_none() {
                return Some(role_attribute_value.into());
            }
        }
        None
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "The HTML element with the interactive role "<Emphasis>{state}</Emphasis>" is not focusable."
                },
            ).note(markup! {
                "A non-interactive HTML element that is not focusable may not be reachable for users that rely on keyboard navigation, even with an added role like "<Emphasis>{state}</Emphasis>"."
            })
            .note(markup! {
                "Add a tabindex attribute to make this element focusable."
            }),
        )
    }
}

/// Checks if the given role value is interactive or not based on ARIA roles.
///
/// Composite roles (such as `menu`) are excluded because they represent containers of
/// interactive descendants rather than directly interactive elements themselves.
fn attribute_has_interactive_role(role_attribute_value: &str) -> bool {
    AriaRole::from_roles(role_attribute_value)
        .is_some_and(|role| role.is_interactive() && !role.is_composite())
}
